  // app bundle). Try the stable zip name and extract the binary from the app
  // bundle — but only for a real HTTP miss: a stalled/reset link would fail
  // the zip the same way.
  if (outcome.isHttpFailure && Platform.isMacOS) {
    final zipAsset = _zipAssetName();
    if (zipAsset != null) {
      _say('archive not found — trying $zipAsset…');
      return fallbackZipUpdate(
        client,
        tag,
        zipAsset,
        target,
        latest,
        runProcess,
        pem: pem,
        stallTimeout: stallTimeout,
        totalTimeout: totalTimeout,
      );
    }
  }
  if (outcome.isHttpFailure) {
    _warn('download failed (HTTP ${outcome.statusCode}): $url');
  } else {
    _warn('download failed (network): ${outcome.failureMessage}');
  }
  return 1;
}

/// The macOS zip assets by ABI (uploaded by build-macos.yml).
const _macZipAssets = {
  'macos_arm64': 'fa-macos-arm64-mac.zip',
  'macos_x64': 'fa-macos-x64-mac.zip',
};

/// The stable zip asset name for macOS. The caller reaches this only on
/// macOS; the const-table lookup keeps non-macOS runners cost-free
/// (gh-1713).
String? _zipAssetName() => _macZipAssets[Abi.current().toString()];

/// Extracts the `Fa.app/Contents/MacOS/Fa` binary bytes from a decoded
/// macOS `.zip` archive, or `null` if the entry is missing.
List<int>? _extractMacBinary(Archive archive) {
  for (final entry in archive) {
    if (entry.name.endsWith('Contents/MacOS/Fa') && entry.isFile) {
      return entry.content as List<int>;
    }
  }
  return null;
}

